pub const JaideWorldClassTrainer = struct {
    quantum_sfd: QuantumEnhancedSFD,
    rsf_layers: []OptimizedRSF,
    ssi_memory: EnhancedSSIMemory,
    zkml_prover: ZKMLProver,

    learning_rate: f32,
    current_epoch: usize,
    total_epochs: usize,

    // Performance metrics
    training_losses: std.ArrayList(f32),
    validation_losses: std.ArrayList(f32),
    surprise_metrics: std.ArrayList(f32),

    allocator: Allocator,

    pub fn init(allocator: Allocator, config: TrainerConfig) !JaideWorldClassTrainer {
        var qsfd = try QuantumEnhancedSFD.init(
            allocator,
            config.param_size,
            config.num_qubits,
            config.sfd_config,
            config.grng_config
        );
        errdefer qsfd.deinit();

        var rsf_layers = try allocator.alloc(OptimizedRSF, config.num_layers);
        errdefer allocator.free(rsf_layers);

        var i: usize = 0;
        while (i < config.num_layers) : (i += 1) {
            rsf_layers[i] = try OptimizedRSF.init(
                allocator,
                config.hidden_dim,
                config.hidden_dim,
                config.hidden_dim
            );
        }

        var ssi = try EnhancedSSIMemory.init(
            allocator,
            config.memory_capacity,
            config.hidden_dim,
            config.num_memory_clusters
        );
        errdefer ssi.deinit();

        var zkml = try ZKMLProver.init(allocator, config.zkml_circuit_path);
        errdefer zkml.deinit();

        return JaideWorldClassTrainer{
            .quantum_sfd = qsfd,
            .rsf_layers = rsf_layers,
            .ssi_memory = ssi,
            .zkml_prover = zkml,
            .learning_rate = config.initial_lr,
            .current_epoch = 0,
            .total_epochs = config.total_epochs,
            .training_losses = std.ArrayList(f32).init(allocator),
            .validation_losses = std.ArrayList(f32).init(allocator),
            .surprise_metrics = std.ArrayList(f32).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *JaideWorldClassTrainer) void {
        self.quantum_sfd.deinit();

        for (self.rsf_layers) |*layer| {
            layer.deinit();
        }
        self.allocator.free(self.rsf_layers);

        self.ssi_memory.deinit();
        self.zkml_prover.deinit();

        self.training_losses.deinit();
        self.validation_losses.deinit();
        self.surprise_metrics.deinit();
    }

    pub fn trainEpoch(self: *JaideWorldClassTrainer, training_data: []TrainingBatch) !void {
        var epoch_loss: f64 = 0.0;
        var epoch_surprise: f64 = 0.0;

        for (training_data, 0..) |batch, batch_idx| {
            // Forward pass through RSF layers with RRN
            var hidden = batch.input;

            for (self.rsf_layers) |*layer| {
                var layer_out = try layer.forwardWithRRN(&hidden);
                if (batch_idx > 0) hidden.deinit();
                hidden = layer_out;
            }
            defer hidden.deinit();

            // Compute loss
            const loss = try self.computeLoss(&hidden, &batch.target);
            epoch_loss += @as(f64, loss);

            // Backward pass with GRNG-SFD
            var gradients = try self.computeGradients(&hidden, &batch.target);
            defer gradients.deinit();

            // Adaptive learning rate schedule
            const lr = self.learning_rate * self.quantum_sfd.grng_sfd.base_sfd.ampSchedule(
                self.current_epoch,
                self.quantum_sfd.grng_sfd.base_sfd.warmup_steps,
                self.total_epochs
            );

            // Quantum-classical hybrid update
            var params = try self.collectAllParameters();
            defer params.deinit();

            try self.quantum_sfd.hybridQuantumClassicalUpdate(&gradients, &params, lr);

            // Update SSI memory with predictive surprise
            const context_history = try self.getRecentContextHistory(5);
            defer self.allocator.free(context_history);

            try self.ssi_memory.storePredictiveSuprise(&hidden, context_history);

            const surprise = try self.ssi_memory.surprise_predictor.predictSurprise(&hidden, context_history);
            epoch_surprise += @as(f64, surprise);

            // Generate ZK proof for this batch (periodically)
            if (batch_idx % 100 == 0) {
                const model_hash = try self.computeModelHash();
                const proof = try self.zkml_prover.proveInference(&batch.input, &hidden, model_hash);

                // Verify immediately
                const verified = try self.zkml_prover.verifyProof(&proof);
                if (!verified) {
                    std.log.warn("ZK proof verification failed for batch {}", .{batch_idx});
                }
            }

            // Adaptive quantum Fisher weight
            if (batch_idx % 50 == 0 and self.validation_losses.items.len > 0) {
                const train_loss = @as(f32, @floatCast(epoch_loss / @as(f64, @floatFromInt(batch_idx + 1))));
                const val_loss = self.validation_losses.items[self.validation_losses.items.len - 1];
                self.quantum_sfd.adaptiveQuantumWeight(train_loss, val_loss);
            }
        }

        // Record epoch metrics
        const avg_loss = @as(f32, @floatCast(epoch_loss / @as(f64, @floatFromInt(training_data.len))));
        const avg_surprise = @as(f32, @floatCast(epoch_surprise / @as(f64, @floatFromInt(training_data.len))));

        try self.training_losses.append(avg_loss);
        try self.surprise_metrics.append(avg_surprise);

        self.current_epoch += 1;

        std.log.info("Epoch {} complete. Loss: {d:.4}, Surprise: {d:.4}, QFisher weight: {d:.3}", .{
            self.current_epoch,
            avg_loss,
            avg_surprise,
            self.quantum_sfd.quantum_fisher_weight,
        });
    }

