const std = @import("std");
const Allocator = std.mem.Allocator;
const Tensor = @import("../core/tensor.zig").Tensor;

pub const LossFn = *const fn (params: *const Tensor, context: ?*anyopaque) anyerror!f32;

pub const SFDConfig = struct {
    beta1: f32 = 0.9,
    beta2: f32 = 0.999,
    eps: f32 = 1e-8,
    clip_threshold: f32 = 1.0,
    fisher_max: f32 = 1e6,
    warmup_steps: usize = 10,
    finite_diff_eps: f32 = 1e-5,
    second_order_eps: f32 = 1e-4,
};

pub const GRNGConfig = struct {
    lambda_gr: f32 = 0.01,
    kalman_process_noise: f32 = 1e-6,
    kalman_measurement_noise: f32 = 1e-4,
    fim_approx_rank: usize = 32,
    enable_bayesian_mode: bool = true,
