pub const SFD = struct {
    fisher_diag: Tensor,
    momentum_buffer: Tensor,
    velocity_buffer: Tensor,
    beta1: f32,
    beta2: f32,
    eps: f32,
    clip_threshold: f32,
    fisher_max: f32,
    warmup_steps: usize,
    step_count: usize,
    allocator: Allocator,
    param_size: usize,
    initialized: bool,

    pub fn init(allocator: Allocator, param_size: usize) !SFD {
        return initWithConfig(allocator, param_size, .{});
    }

    pub fn initWithConfig(allocator: Allocator, param_size: usize, config: SFDConfig) !SFD {
        if (param_size == 0) return error.InvalidParamSize;
        if (config.beta1 <= 0.0 or config.beta1 >= 1.0) return error.InvalidBeta1;
        if (config.beta2 <= 0.0 or config.beta2 >= 1.0) return error.InvalidBeta2;
        if (config.eps <= 0.0) return error.InvalidEpsilon;
        if (config.clip_threshold <= 0.0) return error.InvalidClipThreshold;

        const shape = [_]usize{param_size};

        var diag = try Tensor.init(allocator, &shape);
        errdefer diag.deinit();
        try diag.fill(1.0);

        var momentum = try Tensor.init(allocator, &shape);
        errdefer momentum.deinit();
        try momentum.fill(0.0);

        var velocity = try Tensor.init(allocator, &shape);
        errdefer velocity.deinit();
        try velocity.fill(0.0);

        return SFD{
            .fisher_diag = diag,
            .momentum_buffer = momentum,
            .velocity_buffer = velocity,
            .beta1 = config.beta1,
            .beta2 = config.beta2,
            .eps = config.eps,
            .clip_threshold = config.clip_threshold,
            .fisher_max = config.fisher_max,
            .warmup_steps = config.warmup_steps,
            .step_count = 0,
            .allocator = allocator,
            .param_size = param_size,
            .initialized = true,
        };
    }

    pub fn deinit(self: *SFD) void {
        if (!self.initialized) return;
        self.fisher_diag.deinit();
        self.momentum_buffer.deinit();
        self.velocity_buffer.deinit();
        self.initialized = false;
    }

    pub fn update(self: *SFD, gradients: *const Tensor, params: *Tensor, lr: f32) !void {
        if (!self.initialized) return error.NotInitialized;
        if (!std.math.isFinite(lr) or lr < 0.0) return error.InvalidLearningRate;

        const grad_count = gradients.data.len;
        const param_count = params.data.len;

        if (grad_count != param_count) return error.ShapeMismatch;
        if (grad_count != self.param_size) return error.ShapeMismatch;

        self.step_count +|= 1;
        const step_f = @as(f32, @floatFromInt(self.step_count));

        const grad_data = gradients.data;
        const param_data = params.data;
        const momentum_data = self.momentum_buffer.data;
        const velocity_data = self.velocity_buffer.data;
        const fisher_data = self.fisher_diag.data;

        const warmup_steps_f = @as(f32, @floatFromInt(self.warmup_steps));
        const warmup_factor: f32 = if (self.step_count <= self.warmup_steps and self.warmup_steps > 0)
            step_f / warmup_steps_f
        else
            1.0;

        const beta1_power = std.math.pow(f32, self.beta1, step_f);
        const beta2_power = std.math.pow(f32, self.beta2, step_f);
        const m_correction = 1.0 - beta1_power;
        const v_correction = 1.0 - beta2_power;

        var i: usize = 0;
        while (i < self.param_size) : (i += 1) {
            const g = grad_data[i];

            if (!std.math.isFinite(g)) continue;

            momentum_data[i] = self.beta1 * momentum_data[i] + (1.0 - self.beta1) * g;
            velocity_data[i] = self.beta2 * velocity_data[i] + (1.0 - self.beta2) * g * g;

            var m_hat = momentum_data[i];
            var v_hat = velocity_data[i];

            if (m_correction > 1e-10) {
                m_hat = momentum_data[i] / m_correction;
            }
            if (v_correction > 1e-10) {
                v_hat = velocity_data[i] / v_correction;
            }

            const sqrt_v = std.math.sqrt(@max(0.0, v_hat));
            const adaptive_lr = lr * warmup_factor / (sqrt_v + self.eps);

            fisher_data[i] = self.beta2 * fisher_data[i] + (1.0 - self.beta2) * g * g;
            fisher_data[i] = @min(fisher_data[i], self.fisher_max);
            if (!std.math.isFinite(fisher_data[i])) {
                fisher_data[i] = 1.0;
            }

            const sqrt_fisher = std.math.sqrt(@max(0.0, fisher_data[i]));
            var update_val = m_hat * adaptive_lr / (sqrt_fisher + self.eps);

            update_val = std.math.clamp(update_val, -self.clip_threshold, self.clip_threshold);

            if (std.math.isFinite(update_val)) {
                param_data[i] -= update_val;
            }
        }
    }

    pub fn ampSchedule(_: *const SFD, step: usize, warmup: usize, total: usize) f32 {
        if (warmup == 0) return 1.0;
        if (total <= warmup) return 1.0;

        if (step < warmup) {
            return @as(f32, @floatFromInt(step)) / @as(f32, @floatFromInt(warmup));
        }

        const progress_num = step - warmup;
        const progress_denom = total - warmup;

        if (progress_denom == 0) return 0.5;

        var progress = @as(f32, @floatFromInt(progress_num)) / @as(f32, @floatFromInt(progress_denom));
        progress = @min(progress, 1.0);

        return 0.5 * (1.0 + std.math.cos(std.math.pi * progress));
    }
};

pub const GRNG_SFD = struct {
    base_sfd: SFD,
    kalman_state_mean: Tensor,
    kalman_state_covariance: Tensor,
    kalman_gain: Tensor,
    gradient_history: []Tensor,
    history_capacity: usize,
    history_index: usize,
    lambda_gr: f32,
    process_noise_q: f32,
    measurement_noise_r: f32,
    allocator: Allocator,
    initialized: bool,

    pub fn init(allocator: Allocator, param_size: usize, sfd_config: SFDConfig, grng_config: GRNGConfig) !GRNG_SFD {
        const shape = [_]usize{param_size};

        var base = try SFD.initWithConfig(allocator, param_size, sfd_config);
        errdefer base.deinit();

        var k_mean = try Tensor.zeros(allocator, &shape);
        errdefer k_mean.deinit();

        const cov_shape = [_]usize{ param_size, grng_config.fim_approx_rank };
        var k_cov = try Tensor.init(allocator, &cov_shape);
        errdefer k_cov.deinit();
        try k_cov.fill(1.0);

        var k_gain = try Tensor.zeros(allocator, &shape);
        errdefer k_gain.deinit();

        const history_cap: usize = 10;
        var grad_hist = try allocator.alloc(Tensor, history_cap);
        errdefer allocator.free(grad_hist);

        for (grad_hist, 0..) |*g, i| {
            g.* = try Tensor.zeros(allocator, &shape);
            errdefer {
                var j: usize = 0;
                while (j < i) : (j += 1) {
                    grad_hist[j].deinit();
                }
            }
        }

        return GRNG_SFD{
            .base_sfd = base,
            .kalman_state_mean = k_mean,
            .kalman_state_covariance = k_cov,
            .kalman_gain = k_gain,
            .gradient_history = grad_hist,
            .history_capacity = history_cap,
            .history_index = 0,
            .lambda_gr = grng_config.lambda_gr,
            .process_noise_q = grng_config.kalman_process_noise,
            .measurement_noise_r = grng_config.kalman_measurement_noise,
            .allocator = allocator,
            .initialized = true,
        };
    }

    pub fn deinit(self: *GRNG_SFD) void {
        if (!self.initialized) return;

        self.base_sfd.deinit();
        self.kalman_state_mean.deinit();
        self.kalman_state_covariance.deinit();
        self.kalman_gain.deinit();

        for (self.gradient_history) |*g| {
            g.deinit();
        }
        self.allocator.free(self.gradient_history);

        self.initialized = false;
    }

    pub fn updateWithGRNG(self: *GRNG_SFD, gradients: *const Tensor, params: *Tensor, lr: f32) !void {
        if (!self.initialized) return error.NotInitialized;

        const grad_data = gradients.data;
        const param_size = grad_data.len;

        const gr_penalty = try self.computeGradientRegularization(gradients);
        defer gr_penalty.deinit();

        const hist_idx = self.history_index % self.history_capacity;
        try self.gradient_history[hist_idx].copyFrom(gradients);
        self.history_index +|= 1;

        try self.kalmanPredictionStep();
        try self.kalmanUpdateStep(gradients);

        var natural_grad = try Tensor.init(self.allocator, gradients.shape.dims);
        defer natural_grad.deinit();

        const k_gain_data = self.kalman_gain.data;
        const gr_data = gr_penalty.data;

        var i: usize = 0;
        while (i < param_size) : (i += 1) {
            natural_grad.data[i] = k_gain_data[i] * (grad_data[i] + self.lambda_gr * gr_data[i]);
        }

        const natural_grad_norm = natural_grad.normL2();
        if (natural_grad_norm > self.base_sfd.clip_threshold) {
            const scale = self.base_sfd.clip_threshold / (natural_grad_norm + self.base_sfd.eps);
            try natural_grad.mulScalar(scale);
        }

        try self.updateFisherWithRegularization(gradients, &gr_penalty);

        try self.base_sfd.update(&natural_grad, params, lr);
    }

    fn computeGradientRegularization(self: *GRNG_SFD, current_grad: *const Tensor) !Tensor {
        var gr_penalty = try Tensor.zeros(self.allocator, current_grad.shape.dims);
        errdefer gr_penalty.deinit();

        const current_data = current_grad.data;
        const n = current_data.len;

        const hist_size = @min(self.history_index, self.history_capacity);
        if (hist_size < 2) {
            return gr_penalty;
        }

        var i: usize = 0;
        while (i < n) : (i += 1) {
            var mean: f64 = 0.0;
            var m2: f64 = 0.0;

            var k: usize = 0;
            while (k < hist_size) : (k += 1) {
                const val = self.gradient_history[k].data[i];
                const delta = @as(f64, val) - mean;
                mean += delta / @as(f64, @floatFromInt(k + 1));
                const delta2 = @as(f64, val) - mean;
                m2 += delta * delta2;
            }

            const variance = if (hist_size > 1) m2 / @as(f64, @floatFromInt(hist_size - 1)) else 0.0;
            const std_dev = std.math.sqrt(@max(0.0, variance));

            const deviation = @as(f64, current_data[i]) - mean;
            gr_penalty.data[i] = @floatCast(deviation / (@max(std_dev, 1e-8)));
        }

        return gr_penalty;
    }

    fn kalmanPredictionStep(self: *GRNG_SFD) !void {
        const cov_data = self.kalman_state_covariance.data;
        const q_noise = self.process_noise_q;

        for (cov_data) |*val| {
            val.* += q_noise;
            val.* = @min(val.*, 1e3);
        }
    }

    fn kalmanUpdateStep(self: *GRNG_SFD, measurement: *const Tensor) !void {
        const meas_data = measurement.data;
        const mean_data = self.kalman_state_mean.data;
        const cov_data = self.kalman_state_covariance.data;
        const gain_data = self.kalman_gain.data;
        const r_noise = self.measurement_noise_r;

        const n = mean_data.len;
        const rank = self.kalman_state_covariance.shape.dims[1];

        var i: usize = 0;
        while (i < n) : (i += 1) {
            const innovation = meas_data[i] - mean_data[i];

            var p_trace: f32 = 0.0;
            var j: usize = 0;
            while (j < rank) : (j += 1) {
                const cov_idx = i * rank + j;
                if (cov_idx < cov_data.len) {
                    p_trace += cov_data[cov_idx];
                }
            }
            const s_inv = 1.0 / (p_trace / @as(f32, @floatFromInt(rank)) + r_noise + 1e-8);

            gain_data[i] = (p_trace / @as(f32, @floatFromInt(rank))) * s_inv;
            gain_data[i] = std.math.clamp(gain_data[i], 0.0, 1.0);

            mean_data[i] += gain_data[i] * innovation;

            const reduction_factor = 1.0 - gain_data[i];
            var k: usize = 0;
            while (k < rank) : (k += 1) {
                const cov_idx = i * rank + k;
                if (cov_idx < cov_data.len) {
                    cov_data[cov_idx] *= reduction_factor;
                    cov_data[cov_idx] = @max(cov_data[cov_idx], 1e-8);
                }
            }
        }
    }

    fn updateFisherWithRegularization(self: *GRNG_SFD, grads: *const Tensor, gr_penalty: *const Tensor) !void {
        const fisher_data = self.base_sfd.fisher_diag.data;
        const grad_data = grads.data;
        const penalty_data = gr_penalty.data;

        const beta = self.base_sfd.beta2;
        const lambda = self.lambda_gr;

        for (fisher_data, 0..) |*f, i| {
            if (i >= grad_data.len) break;

            const regularized_grad = grad_data[i] + lambda * penalty_data[i];
            const new_fisher = regularized_grad * regularized_grad;

            f.* = beta * f.* + (1.0 - beta) * new_fisher;
            f.* = @min(f.*, self.base_sfd.fisher_max);

            if (!std.math.isFinite(f.*)) {
                f.* = 1.0;
            }
        }
    }
};

pub const QuantumCircuit = struct {
    num_qubits: usize,
    gates: std.ArrayList(QuantumGate),
    allocator: Allocator,

    const QuantumGate = union(enum) {
        ry: struct { qubit: usize, angle: f32 },
        rz: struct { qubit: usize, angle: f32 },
        cnot: struct { control: usize, target: usize },
        h: struct { qubit: usize },
    };

    pub fn init(allocator: Allocator, num_qubits: usize) !QuantumCircuit {
        return QuantumCircuit{
            .num_qubits = num_qubits,
            .gates = std.ArrayList(QuantumGate).init(allocator),
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *QuantumCircuit) void {
        self.gates.deinit();
    }

    pub fn ry(self: *QuantumCircuit, qubit: usize, angle: f32) !void {
        try self.gates.append(.{ .ry = .{ .qubit = qubit, .angle = angle } });
    }

    pub fn rz(self: *QuantumCircuit, qubit: usize, angle: f32) !void {
        try self.gates.append(.{ .rz = .{ .qubit = qubit, .angle = angle } });
    }

    pub fn cnot(self: *QuantumCircuit, control: usize, target: usize) !void {
        try self.gates.append(.{ .cnot = .{ .control = control, .target = target } });
    }

    pub fn h(self: *QuantumCircuit, qubit: usize) !void {
        try self.gates.append(.{ .h = .{ .qubit = qubit } });
    }

    pub fn simulateExpectation(self: *const QuantumCircuit, allocator: Allocator) !f32 {
        const state_size: usize = @as(usize, 1) << @intCast(self.num_qubits);
        var state_real = try allocator.alloc(f32, state_size);
        defer allocator.free(state_real);
        var state_imag = try allocator.alloc(f32, state_size);
        defer allocator.free(state_imag);

        @memset(state_real, 0.0);
        @memset(state_imag, 0.0);
        state_real[0] = 1.0;

        for (self.gates.items) |gate| {
            switch (gate) {
                .ry => |g| try applyRY(state_real, state_imag, self.num_qubits, g.qubit, g.angle),
                .rz => |g| try applyRZ(state_real, state_imag, self.num_qubits, g.qubit, g.angle),
                .cnot => |g| try applyCNOT(state_real, state_imag, self.num_qubits, g.control, g.target),
                .h => |g| try applyH(state_real, state_imag, self.num_qubits, g.qubit),
            }
        }

        var expectation: f64 = 0.0;
        var i: usize = 0;
        while (i < state_size) : (i += 1) {
            const parity = @popCount(i) % 2;
            const sign: f32 = if (parity == 0) 1.0 else -1.0;
            const prob = state_real[i] * state_real[i] + state_imag[i] * state_imag[i];
            expectation += sign * @as(f64, prob);
        }

        return @floatCast(expectation);
    }
};

fn applyRY(state_real: []f32, state_imag: []f32, num_qubits: usize, qubit: usize, angle: f32) !void {
    const cos_half = std.math.cos(angle / 2.0);
    const sin_half = std.math.sin(angle / 2.0);
    const state_size: usize = @as(usize, 1) << @intCast(num_qubits);
    const qubit_mask: usize = @as(usize, 1) << @intCast(qubit);

    var temp_real = try std.heap.page_allocator.alloc(f32, state_size);
    defer std.heap.page_allocator.free(temp_real);
    var temp_imag = try std.heap.page_allocator.alloc(f32, state_size);
    defer std.heap.page_allocator.free(temp_imag);

    @memcpy(temp_real, state_real);
    @memcpy(temp_imag, state_imag);

    var i: usize = 0;
    while (i < state_size) : (i += 1) {
        if ((i & qubit_mask) == 0) {
            const i_flip = i | qubit_mask;

            state_real[i] = cos_half * temp_real[i] - sin_half * temp_real[i_flip];
            state_imag[i] = cos_half * temp_imag[i] - sin_half * temp_imag[i_flip];

            state_real[i_flip] = sin_half * temp_real[i] + cos_half * temp_real[i_flip];
            state_imag[i_flip] = sin_half * temp_imag[i] + cos_half * temp_imag[i_flip];
        }
    }
}

fn applyRZ(state_real: []f32, state_imag: []f32, num_qubits: usize, qubit: usize, angle: f32) !void {
    const cos_half = std.math.cos(angle / 2.0);
    const sin_half = std.math.sin(angle / 2.0);
    const state_size: usize = @as(usize, 1) << @intCast(num_qubits);
    const qubit_mask: usize = @as(usize, 1) << @intCast(qubit);

    var i: usize = 0;
    while (i < state_size) : (i += 1) {
        if ((i & qubit_mask) != 0) {
            const temp_real = state_real[i];
            state_real[i] = cos_half * temp_real + sin_half * state_imag[i];
            state_imag[i] = cos_half * state_imag[i] - sin_half * temp_real;
        }
    }
}

fn applyCNOT(state_real: []f32, state_imag: []f32, num_qubits: usize, control: usize, target: usize) !void {
    const state_size: usize = @as(usize, 1) << @intCast(num_qubits);
    const control_mask: usize = @as(usize, 1) << @intCast(control);
    const target_mask: usize = @as(usize, 1) << @intCast(target);

    var i: usize = 0;
    while (i < state_size) : (i += 1) {
        if ((i & control_mask) != 0 and (i & target_mask) == 0) {
            const i_flip = i | target_mask;

            const temp_real = state_real[i];
            const temp_imag = state_imag[i];

            state_real[i] = state_real[i_flip];
            state_imag[i] = state_imag[i_flip];

            state_real[i_flip] = temp_real;
            state_imag[i_flip] = temp_imag;
        }
    }
}

fn applyH(state_real: []f32, state_imag: []f32, num_qubits: usize, qubit: usize) !void {
    const inv_sqrt2: f32 = 1.0 / std.math.sqrt(2.0);
    const state_size: usize = @as(usize, 1) << @intCast(num_qubits);
    const qubit_mask: usize = @as(usize, 1) << @intCast(qubit);

    var temp_real = try std.heap.page_allocator.alloc(f32, state_size);
    defer std.heap.page_allocator.free(temp_real);
    var temp_imag = try std.heap.page_allocator.alloc(f32, state_size);
    defer std.heap.page_allocator.free(temp_imag);

    @memcpy(temp_real, state_real);
    @memcpy(temp_imag, state_imag);

    var i: usize = 0;
    while (i < state_size) : (i += 1) {
        if ((i & qubit_mask) == 0) {
            const i_flip = i | qubit_mask;

            state_real[i] = inv_sqrt2 * (temp_real[i] + temp_real[i_flip]);
            state_imag[i] = inv_sqrt2 * (temp_imag[i] + temp_imag[i_flip]);

            state_real[i_flip] = inv_sqrt2 * (temp_real[i] - temp_real[i_flip]);
            state_imag[i_flip] = inv_sqrt2 * (temp_imag[i] - temp_imag[i_flip]);
        }
    }
}

pub const QuantumEnhancedSFD = struct {
    grng_sfd: GRNG_SFD,
    vqe_ansatz_depth: usize,
    entanglement_topology: [][2]usize,
    quantum_fisher_weight: f32,
    num_qubits: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, param_size: usize, num_qubits: usize, sfd_config: SFDConfig, grng_config: GRNGConfig, quantum_config: QuantumConfig) !QuantumEnhancedSFD {
        var grng = try GRNG_SFD.init(allocator, param_size, sfd_config, grng_config);
        errdefer grng.deinit();

        var topology = try allocator.alloc([2]usize, num_qubits);
        errdefer allocator.free(topology);

        var i: usize = 0;
        while (i < num_qubits) : (i += 1) {
            topology[i] = [2]usize{ i, (i + 1) % num_qubits };
        }

        return QuantumEnhancedSFD{
            .grng_sfd = grng,
            .vqe_ansatz_depth = quantum_config.vqe_depth,
            .entanglement_topology = topology,
            .quantum_fisher_weight = quantum_config.quantum_fisher_weight,
            .num_qubits = num_qubits,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *QuantumEnhancedSFD) void {
        self.grng_sfd.deinit();
        self.allocator.free(self.entanglement_topology);
    }

    pub fn quantumFisherInformationMatrix(self: *QuantumEnhancedSFD, params: *const Tensor) !Tensor {
        const n_params = params.data.len;
        const qfim_shape = [_]usize{n_params};
        var qfim = try Tensor.zeros(self.allocator, &qfim_shape);
        errdefer qfim.deinit();

        const shift: f32 = std.math.pi / 2.0;

        var i: usize = 0;
        while (i < n_params) : (i += 1) {
            var circuit_plus = try self.createVQECircuit(params, i, shift);
            defer circuit_plus.deinit();

            var circuit_minus = try self.createVQECircuit(params, i, -shift);
            defer circuit_minus.deinit();

            const expect_plus = try circuit_plus.simulateExpectation(self.allocator);
            const expect_minus = try circuit_minus.simulateExpectation(self.allocator);

            const diff = expect_plus - expect_minus;
            qfim.data[i] = (diff * diff) / 4.0;

            qfim.data[i] += try self.entanglementFisherContribution(i);
        }

        return qfim;
    }

    fn createVQECircuit(self: *QuantumEnhancedSFD, params: *const Tensor, param_idx: usize, shift_angle: f32) !QuantumCircuit {
        var circuit = try QuantumCircuit.init(self.allocator, self.num_qubits);
        errdefer circuit.deinit();

        var layer: usize = 0;
        while (layer < self.vqe_ansatz_depth) : (layer += 1) {
            var q: usize = 0;
            while (q < self.num_qubits) : (q += 1) {
                const p_idx = (layer * self.num_qubits + q) % params.data.len;
                var angle = params.data[p_idx];

                if (p_idx == param_idx) {
                    angle += shift_angle;
                }

                try circuit.ry(q, angle);
                try circuit.rz(q, angle * 0.5);
            }

            for (self.entanglement_topology) |pair| {
                try circuit.cnot(pair[0], pair[1]);
            }
        }

        return circuit;
    }

    fn entanglementFisherContribution(self: *QuantumEnhancedSFD, param_idx: usize) !f32 {
        const qubit_idx = param_idx % self.num_qubits;
        var entanglement_sum: f32 = 0.0;

        for (self.entanglement_topology) |pair| {
            if (pair[0] == qubit_idx or pair[1] == qubit_idx) {
                entanglement_sum += 1.0;
            }
        }

        return entanglement_sum * 0.25;
    }

    pub fn hybridQuantumClassicalUpdate(self: *QuantumEnhancedSFD, gradients: *const Tensor, params: *Tensor, lr: f32) !void {
        var qfim = try self.quantumFisherInformationMatrix(params);
        defer qfim.deinit();

        const classical_fisher = self.grng_sfd.base_sfd.fisher_diag.data;
        const quantum_fisher = qfim.data;
        const alpha = self.quantum_fisher_weight;

        var i: usize = 0;
        while (i < classical_fisher.len and i < quantum_fisher.len) : (i += 1) {
            const hybrid_fisher = alpha * quantum_fisher[i] + (1.0 - alpha) * classical_fisher[i];
            classical_fisher[i] = @min(hybrid_fisher, self.grng_sfd.base_sfd.fisher_max);
        }

        try self.grng_sfd.updateWithGRNG(gradients, params, lr);
    }

    pub fn adaptiveQuantumWeight(self: *QuantumEnhancedSFD, training_loss: f32, validation_loss: f32) void {
        const gen_gap = @abs(validation_loss - training_loss) / (training_loss + 1e-6);

        if (gen_gap > 0.1) {
            self.quantum_fisher_weight = @min(self.quantum_fisher_weight * 1.05, 0.7);
        } else {
            self.quantum_fisher_weight = @max(self.quantum_fisher_weight * 0.98, 0.1);
        }
    }
};

pub const SurprisePredictor = struct {
    hidden_dim: usize,
    hidden_state: Tensor,
    cell_state: Tensor,
    weights_ih: Tensor,
    weights_hh: Tensor,
    bias: Tensor,
    allocator: Allocator,

    pub fn init(allocator: Allocator, input_dim: usize, hidden_dim: usize) !SurprisePredictor {
        const h_shape = [_]usize{hidden_dim};
        var h_state = try Tensor.zeros(allocator, &h_shape);
        errdefer h_state.deinit();

        var c_state = try Tensor.zeros(allocator, &h_shape);
        errdefer c_state.deinit();

        const w_ih_shape = [_]usize{ 4 * hidden_dim, input_dim };
        var w_ih = try Tensor.init(allocator, &w_ih_shape);
        errdefer w_ih.deinit();
        try w_ih.randomize(-0.1, 0.1);

        const w_hh_shape = [_]usize{ 4 * hidden_dim, hidden_dim };
        var w_hh = try Tensor.init(allocator, &w_hh_shape);
        errdefer w_hh.deinit();
        try w_hh.randomize(-0.1, 0.1);

        const b_shape = [_]usize{4 * hidden_dim};
        var bias_t = try Tensor.zeros(allocator, &b_shape);
        errdefer bias_t.deinit();

        return SurprisePredictor{
            .hidden_dim = hidden_dim,
            .hidden_state = h_state,
            .cell_state = c_state,
            .weights_ih = w_ih,
            .weights_hh = w_hh,
            .bias = bias_t,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *SurprisePredictor) void {
        self.hidden_state.deinit();
        self.cell_state.deinit();
        self.weights_ih.deinit();
        self.weights_hh.deinit();
        self.bias.deinit();
    }

    pub fn predictSurprise(self: *SurprisePredictor, input_embedding: *const Tensor, context_history: []const Tensor) !f32 {
        const input_data = input_embedding.data;
        const h_data = self.hidden_state.data;
        const c_data = self.cell_state.data;

        var gates = try Tensor.zeros(self.allocator, &[_]usize{4 * self.hidden_dim});
        defer gates.deinit();

        var i: usize = 0;
        while (i < 4 * self.hidden_dim) : (i += 1) {
            var sum: f64 = @as(f64, self.bias.data[i]);

            var j: usize = 0;
            while (j < input_data.len) : (j += 1) {
                const w_idx = i * input_data.len + j;
                if (w_idx < self.weights_ih.data.len) {
                    sum += @as(f64, self.weights_ih.data[w_idx]) * @as(f64, input_data[j]);
                }
            }

            j = 0;
            while (j < self.hidden_dim) : (j += 1) {
                const w_idx = i * self.hidden_dim + j;
                if (w_idx < self.weights_hh.data.len) {
                    sum += @as(f64, self.weights_hh.data[w_idx]) * @as(f64, h_data[j]);
                }
            }

            gates.data[i] = @floatCast(sum);
        }

        i = 0;
        while (i < self.hidden_dim) : (i += 1) {
            const i_gate = sigmoid(gates.data[i]);
            const f_gate = sigmoid(gates.data[i + self.hidden_dim]);
            const g_gate = std.math.tanh(gates.data[i + 2 * self.hidden_dim]);
            const o_gate = sigmoid(gates.data[i + 3 * self.hidden_dim]);

            c_data[i] = f_gate * c_data[i] + i_gate * g_gate;
            h_data[i] = o_gate * std.math.tanh(c_data[i]);
        }

        const h_norm = self.hidden_state.normL2();
        const normalized_surprise = std.math.clamp(h_norm / 10.0, 0.0, 1.0);

        var context_factor: f32 = 1.0;
        if (context_history.len > 0) {
            const recent_context = context_history[context_history.len - 1];
            const similarity = try input_embedding.cosineSimilarity(&recent_context);
            context_factor = 1.0 - similarity;
        }

        return normalized_surprise * context_factor;
    }

    fn sigmoid(x: f32) f32 {
        return 1.0 / (1.0 + std.math.exp(-x));
    }
};

pub const ClusterNode = struct {
    centroid: Tensor,
    member_indices: std.ArrayList(usize),
    surprise_mean: f32,
    last_updated: i64,
};

pub const EnhancedSSIMemory = struct {
    surprise_threshold: f32,
    semantic_embeddings: []Tensor,
    surprise_scores: []f32,
    access_counts: []u64,
    temporal_decay_rate: f32,
    last_access_timestamps: []i64,
    surprise_predictor: SurprisePredictor,
    semantic_clusters: []ClusterNode,
    num_clusters: usize,
    capacity: usize,
    current_size: usize,
    allocator: Allocator,

    pub fn init(allocator: Allocator, capacity: usize, embedding_dim: usize, num_clusters: usize) !EnhancedSSIMemory {
        var embeddings = try allocator.alloc(Tensor, capacity);
        errdefer allocator.free(embeddings);

        const emb_shape = [_]usize{embedding_dim};
        for (embeddings) |*e| {
            e.* = try Tensor.zeros(allocator, &emb_shape);
        }

        var surprise_scores = try allocator.alloc(f32, capacity);
        errdefer allocator.free(surprise_scores);
        @memset(surprise_scores, 0.0);

        var access_counts = try allocator.alloc(u64, capacity);
        errdefer allocator.free(access_counts);
        @memset(access_counts, 0);

        var timestamps = try allocator.alloc(i64, capacity);
        errdefer allocator.free(timestamps);
        @memset(timestamps, 0);

        var predictor = try SurprisePredictor.init(allocator, embedding_dim, 128);
        errdefer predictor.deinit();

        var clusters = try allocator.alloc(ClusterNode, num_clusters);
        errdefer allocator.free(clusters);

        for (clusters) |*cluster| {
            cluster.* = ClusterNode{
                .centroid = try Tensor.zeros(allocator, &emb_shape),
                .member_indices = std.ArrayList(usize).init(allocator),
                .surprise_mean = 0.0,
                .last_updated = 0,
            };
        }

        return EnhancedSSIMemory{
            .surprise_threshold = 0.5,
            .semantic_embeddings = embeddings,
            .surprise_scores = surprise_scores,
            .access_counts = access_counts,
            .temporal_decay_rate = 0.95,
            .last_access_timestamps = timestamps,
            .surprise_predictor = predictor,
            .semantic_clusters = clusters,
            .num_clusters = num_clusters,
            .capacity = capacity,
            .current_size = 0,
            .allocator = allocator,
        };
    }

    pub fn deinit(self: *EnhancedSSIMemory) void {
        for (self.semantic_embeddings) |*e| {
            e.deinit();
        }
        self.allocator.free(self.semantic_embeddings);
        self.allocator.free(self.surprise_scores);
        self.allocator.free(self.access_counts);
        self.allocator.free(self.last_access_timestamps);

        self.surprise_predictor.deinit();

        for (self.semantic_clusters) |*cluster| {
            cluster.centroid.deinit();
            cluster.member_indices.deinit();
        }
        self.allocator.free(self.semantic_clusters);
    }

    pub fn storePredictiveSuprise(self: *EnhancedSSIMemory, embedding: *const Tensor, context_history: []const Tensor) !void {
        const predicted_surprise = try self.surprise_predictor.predictSurprise(embedding, context_history);
        const actual_surprise = try self.computeActualSurprise(embedding, context_history);

        try self.calibratePredictor(embedding, actual_surprise);

        const final_surprise = @max(predicted_surprise, actual_surprise);

        if (final_surprise > self.surprise_threshold) {
            try self.storeWithSurprise(embedding, final_surprise);
        }
    }

    fn computeActualSurprise(self: *EnhancedSSIMemory, embedding: *const Tensor, context: []const Tensor) !f32 {
        _ = context;

        if (self.current_size == 0) return 1.0;

        var min_distance: f32 = std.math.inf(f32);

        var i: usize = 0;
        while (i < self.current_size) : (i += 1) {
            const dist = try embedding.euclideanDistance(&self.semantic_embeddings[i]);
            min_distance = @min(min_distance, dist);
        }

        const surprise = std.math.clamp(min_distance / 10.0, 0.0, 1.0);
        return surprise;
    }

    fn calibratePredictor(self: *EnhancedSSIMemory, embedding: *const Tensor, target_surprise: f32) !void {
        const predicted = try self.surprise_predictor.predictSurprise(embedding, &[_]Tensor{});
        const error = target_surprise - predicted;

        const lr: f32 = 0.001;

        for (self.surprise_predictor.bias.data) |*b| {
            b.* += lr * error;
        }
    }

    fn storeWithSurprise(self: *EnhancedSSIMemory, embedding: *const Tensor, surprise: f32) !void {
        var insert_idx: usize = 0;

        if (self.current_size < self.capacity) {
            insert_idx = self.current_size;
            self.current_size += 1;
        } else {
            insert_idx = try self.findEvictionCandidate();
        }

        try self.semantic_embeddings[insert_idx].copyFrom(embedding);
        self.surprise_scores[insert_idx] = surprise;
        self.access_counts[insert_idx] = 1;
        self.last_access_timestamps[insert_idx] = std.time.timestamp();

        try self.updateClusters(insert_idx);
    }

    fn findEvictionCandidate(self: *EnhancedSSIMemory) !usize {
        var min_priority: f32 = std.math.inf(f32);
        var evict_idx: usize = 0;

        const current_time = std.time.timestamp();

        var i: usize = 0;
        while (i < self.current_size) : (i += 1) {
            const time_diff = @as(f32, @floatFromInt(current_time - self.last_access_timestamps[i]));
            const decay = std.math.pow(f32, self.temporal_decay_rate, time_diff / 3600.0);

            const decayed_surprise = self.surprise_scores[i] * decay;
            const access_boost = std.math.log2(@as(f32, @floatFromInt(self.access_counts[i] + 1)));

            const priority = decayed_surprise + 0.1 * access_boost;

            if (priority < min_priority) {
                min_priority = priority;
                evict_idx = i;
            }
        }

        return evict_idx;
    }

    fn updateClusters(self: *EnhancedSSIMemory, new_idx: usize) !void {
        var min_dist: f32 = std.math.inf(f32);
        var best_cluster: usize = 0;

        const new_embedding = &self.semantic_embeddings[new_idx];

        for (self.semantic_clusters, 0..) |*cluster, c_idx| {
            const dist = try new_embedding.euclideanDistance(&cluster.centroid);
            if (dist < min_dist) {
                min_dist = dist;
                best_cluster = c_idx;
            }
        }

        try self.semantic_clusters[best_cluster].member_indices.append(new_idx);

        const alpha: f32 = 0.1;
        const centroid_data = self.semantic_clusters[best_cluster].centroid.data;
        const new_data = new_embedding.data;

        for (centroid_data, 0..) |*c, i| {
            if (i < new_data.len) {
                c.* = (1.0 - alpha) * c.* + alpha * new_data[i];
            }
        }

        const n_members = @as(f32, @floatFromInt(self.semantic_clusters[best_cluster].member_indices.items.len));
        self.semantic_clusters[best_cluster].surprise_mean = (self.semantic_clusters[best_cluster].surprise_mean * (n_members - 1.0) + self.surprise_scores[new_idx]) / n_members;

        self.semantic_clusters[best_cluster].last_updated = std.time.timestamp();
    }

    pub fn retrieveTopK(self: *EnhancedSSIMemory, query: *const Tensor, k: usize) ![]usize {
        var scores = try self.allocator.alloc(f32, self.current_size);
        defer self.allocator.free(scores);

        const current_time = std.time.timestamp();

        var i: usize = 0;
        while (i < self.current_size) : (i += 1) {
            const similarity = try query.cosineSimilarity(&self.semantic_embeddings[i]);

            const time_diff = @as(f32, @floatFromInt(current_time - self.last_access_timestamps[i]));
            const recency = std.math.exp(-time_diff / 86400.0);

            scores[i] = 0.6 * similarity + 0.3 * self.surprise_scores[i] + 0.1 * recency;
        }

        var indices = try self.allocator.alloc(usize, self.current_size);
        defer self.allocator.free(indices);

        for (indices, 0..) |*idx, j| {
            idx.* = j;
        }

        const actual_k = @min(k, self.current_size);
        var j: usize = 0;
        while (j < actual_k) : (j += 1) {
            var max_idx = j;
            var m: usize = j + 1;
            while (m < self.current_size) : (m += 1) {
                if (scores[indices[m]] > scores[indices[max_idx]]) {
                    max_idx = m;
                }
            }

            const temp = indices[j];
            indices[j] = indices[max_idx];
            indices[max_idx] = temp;

            self.access_counts[indices[j]] += 1;
            self.last_access_timestamps[indices[j]] = current_time;
        }

        var result = try self.allocator.alloc(usize, actual_k);
        @memcpy(result, indices[0..actual_k]);

        return result;
    }
};

