        const grng_config = GRNGConfig{};
        const quantum_config = QuantumConfig{};

        var qsfd = try QuantumEnhancedSFD.init(allocator, param_size, quantum_config.num_qubits, sfd_config, grng_config, quantum_config);
        errdefer qsfd.deinit();

        var ssi = try EnhancedSSIMemory.init(allocator, 10000, embedding_dim, 50);
        errdefer ssi.deinit();

        return WorldClassOptimizer{
            .quantum_sfd = qsfd,
            .ssi_memory = ssi,
