fn testQuadraticLoss(params: *const Tensor, context: ?*anyopaque) !f32 {
    _ = context;

    var loss: f64 = 0.0;
    for (params.data) |val| {
        if (std.math.isFinite(val)) {
            loss += @as(f64, val) * @as(f64, val);
        }
    }
    return @floatCast(loss);
}

